{
  "description": "A large quadrupedal creature shown in right-facing profile standing on a light background. The body is lion-like, covered in short tawny-brown fur with a lighter belly and darker shading on the lower chest and back, supported by four muscular legs. The front of the animal has a lion's head with a full shaggy mane around the neck, and the mid-back bears two very large outspread feathered wings. The chest and shoulders are also covered in overlapping feather-like structures that blend into the mane and wings. A long lion-like tail with a dark tuft hangs behind the hind legs.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a lion's head in profile facing right, with a broad muzzle, dark nose, yellow-brown eyes, white whisker pads with whiskers, and a closed mouth with a light chin",
      "where": "at the front end of the body, attached to the neck"
    },
    {
      "part": "ears",
      "looks_like": "two small rounded ears with short fur and darker inner edges",
      "where": "on top of the head, partly set into the mane"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, medium-long fur in tawny and dark brown, forming a ruff around the neck and extending down the chest between the forelegs",
      "where": "encircling the neck and upper chest, behind the head and under the feathered shoulder covering"
    },
    {
      "part": "legs",
      "looks_like": "four sturdy, muscular lion-like legs covered in short tawny fur with lighter fur on the inner and lower parts, with visible joints and musculature",
      "where": "two forelegs under the chest and two hind legs under the rear of the body, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large paw-like feet with rounded toe pads, short light-colored fur on the toes, and visible dark claws",
      "where": "at the bottom ends of each leg, in contact with the ground"
    },
    {
      "part": "tail",
      "looks_like": "a long, slender, fur-covered tail the same tawny color as the body, ending in a dark brown-black tuft of longer hair",
      "where": "extending from the rear of the body, curving down behind the hind legs"
    },
    {
      "part": "wings",
      "looks_like": "two large outspread wings with many layers of overlapping feathers in golden-brown, tan, and dark brown-black at the outer primaries and lower edges, with detailed feather patterning",
      "where": "attached to the upper back behind the shoulders, rising up and extending outward to the left and right"
    },
    {
      "part": "feathers",
      "looks_like": "dense overlapping feathers in shades of gold, tan and brown with darker tips, covering the wings and continuing as a scaled-like feathered mantle over the shoulders and down the front of the chest",
      "where": "on the wings and on the shoulders and upper chest, blending into the mane"
    }
  ],
  "attached_objects": [],
  "animals": ["lion", "eagle"],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 2,
  "extra_limb_pieces": 0,
  "tails": 1
}
